import{_ as a,o as r,c as o,a2 as n}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"الأسئلة الشائعة (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"ar/96-常见问题FAQ.md","filePath":"ar/96-常见问题FAQ.md","lastUpdated":null}'),e={name:"ar/96-常见问题FAQ.md"};function s(l,t,i,h,d,p){return r(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="الأسئلة-الشائعة-faq" tabindex="-1">الأسئلة الشائعة (FAQ) <a class="header-anchor" href="#الأسئلة-الشائعة-faq" aria-label="Permalink to &quot;الأسئلة الشائعة (FAQ)&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>96</td></tr><tr><td>الوحدة</td><td>الملاحق والمواد المرجعية</td></tr><tr><td>الكلمات المفتاحية</td><td>الأسئلة الشائعة، FAQ، الإجابة عن الاستفسارات، توضيحات الإعدادات، دليل الدخول</td></tr></tbody></table><h2 id="أولاً-ملاحظات" tabindex="-1">أولاً: ملاحظات <a class="header-anchor" href="#أولاً-ملاحظات" aria-label="Permalink to &quot;أولاً: ملاحظات&quot;">​</a></h2><p>تضم هذه الوثيقة الأسئلة الشائعة وإجاباتها عن منظومة إعدادات حضارة التكافل المرساة، مرتبة حسب الموضوع. تغطي الأسئلة جميع الجوانب: المفاهيم الجوهرية للرؤية الكونية، ونظام الزراعة، والنظام الاجتماعي، والنظام القانوني، والتفاعل عبر الأبعاد، وقواعد الزمن، وغير ذلك. هدف هذه الوثيقة هو تقديم دليل دخول سريع للقراء الذين يتعرفون على إعدادات حضارة التكافل المرساة لأول مرة، مع تقديم إجابات موثوقة عن الأسئلة الشائعة للباحثين المتعمقين. هذه الوثيقة محدثة باستمرار؛ وستُضاف إليها أسئلة وأجوبة جديدة تباعاً وفق ملاحظات القراء.</p><h2 id="ثانياً-الرؤية-الكونية-والمفاهيم-الجوهرية" tabindex="-1">ثانياً: الرؤية الكونية والمفاهيم الجوهرية <a class="header-anchor" href="#ثانياً-الرؤية-الكونية-والمفاهيم-الجوهرية" aria-label="Permalink to &quot;ثانياً: الرؤية الكونية والمفاهيم الجوهرية&quot;">​</a></h2><p><strong>س1: ما هو المبدأ المحوري لحضارة التكافل المرساة؟</strong> ج: المبدأ المحوري لحضارة التكافل المرساة هو «مناهضة الافتراس، والدعوة إلى التكافل». تحديداً، تعارض أنظمة الزراعة الافتراسية التي تقوم على حساب التهام طاقة الضعفاء أو حظوظهم أو حتى أصولهم، وتدعو إلى التطور المشترك عبر التعاون التكافلي. المفهوم الجوهري للحضارة هو «إعادة حق اختيار القدر والتطور إلى جميع الكائنات»، وخطوطها الأساسية هي «المزيد من العمل، المزيد من العائد؛ نمو ذاتي؛ طريق لكل فرد؛ تقدم مشترك لعشرة آلاف عرق».</p><p><strong>س2: ماذا يعني مبدأ «الواقع أساس»؟</strong> ج: «الواقع أساس» أحد المواقف الجوهرية لحضارة التكافل المرساة، ويعني أن العالم الحقيقي هو العالم الحقيقي الوحيد، وأن عالم الروايات تجربة فكرية افتراضية. في بناء الإعدادات، يُستكمل ما ينقص الخيال من الواقع، ويُبتكر ما لا وجود له في الواقع عبر الارتقاء استناداً إلى القوانين الموضوعية. يضمن هذا المبدأ الاتساق المنطقي والإحساس الواقعي لمنظومة الإعدادات، ويتجنب انهيار الإعدادات الناجم عن التخيل المجرد.</p><p><strong>س3: ما العلاقة بين كون هنغ يوان والكون؟</strong> ج: الاسم الكامل لكون هنغ يوان هو «كون وانلينغ هنغماو الأصلاني». وهو كامل منطقة الكون التي تسكنها وتحكمها حضارة التكافل المرساة. ليس كوناً فيزيائياً واحداً بالمعنى العادي، بل كيان مركب من أربعة مستويات — الأبعاد المادية، والطبقات الطاقية، ومجال الوعي، وشبكة القوانين. يمكن فهمه على أنه نظام كوني فائق يضم أبعاداً لا تعد ولا تحصى، وآلية المرساة هي وسيلته المحورية للضبط.</p><h2 id="ثالثاً-نظام-الزراعة" tabindex="-1">ثالثاً: نظام الزراعة <a class="header-anchor" href="#ثالثاً-نظام-الزراعة" aria-label="Permalink to &quot;ثالثاً: نظام الزراعة&quot;">​</a></h2><p><strong>س4: كيف نشأت أنظمة الزراعة الأصلانية الثلاثمائة؟</strong> ج: الأنظمة الثلاثمائة ليست مهارات مختلقة من صنع الإنسان، بل مسارات زراعة أرثوذكسية استُخلصت مباشرة من القوانين الأصلانية للكون وتحقق منها المراسي. في فترة تأسيس النظام التكافلي، أجرى الفريق بقيادة «Sānbǎi Shī» تنقيباً وتنظيماً منهجيين لقوانين الكون، وخلص في النهاية إلى تلخيص ثلاثمائة نظام زراعة تغطي جميع أبعاد التطور. تنقسم هذه الأنظمة إلى ست فئات كبرى — الاستنتاج الأصلاني، ودورة الحياة، والمبادئ القانونية المكانية، وارتقاء الوعي، والشبكة التكافلية، والهندسة التطبيقية — بخمسين نظاماً في كل فئة.</p><p><strong>س5: لماذا تُسمى الأنظمة الثلاثة الأولى «الأسس الأصلانية الثلاثة»؟</strong> ج: الأنظمة الثلاثة الأولى — الاستنتاج التكراري (النظام 1)، ودورة الحياة (النظام 2)، وتسير المبادئ القانونية المكانية (النظام 3) — هي أساس زراعة جميع الأنظمة الأخرى. يقدم نظام الاستنتاج التكراري أساس الحكمة والمنهجية؛ ويقدم نظام دورة الحياة أساس الطاقة الحياتية؛ ويقدم نظام تسيير المبادئ القانونية المكانية أساس العمليات المكانية والقانونية. ويُنصح مزارعو أي نظام آخر بأن يمارسوا أولاً واحداً على الأقل من الأسس الأصلانية الثلاثة لإرساء أساس تطوري راسخ.</p><p><strong>س6: ما هي ثمرة المضاعفة؟ وما علاقتها بـ One Piece؟</strong> ج: ثمرة المضاعفة واحدة من «مزايا الانطلاق» لحضارة التكافل المرساة، مصدرها إعداد ثمرة المضاعفة في عالم One Piece. في كون هنغ يوان، خضعت ثمرة المضاعفة لتطبيق تقني: فهي قادرة على رفع قدرة المزارع الاستنتاجية مئة ضعف، وتُعد الأداة المساعدة المحورية لنظام الاستنتاج التكراري. يجسد هذا الإعداد مبدأ «استكمال ما ينقص الخيال من الواقع، وابتكار ما لا وجود له في الواقع بالارتقاء استناداً إلى القوانين» — إذ تُدمج الإعدادات الممتعة من الأعمال الخيالية في المنظومة التقنية للحضارة التكافلية بعد تحويلها وفق القوانين.</p><p><strong>س7: ما هي استراتيجية التنشيط بنسبة 20٪؟ ولماذا 20٪؟</strong> ج: استراتيجية التنشيط بنسبة 20٪ هدف استراتيجي مرحلي لحضارة التكافل المرساة، يرمي إلى تنشيط 20٪ من جميع كائنات الكون في المرحلة الأولى كقوى الأبعاد العليا. اختيار نسبة 20٪ مبني على التحليل الديناميكي للشبكة التكافلية — فعندما تبلغ 20٪ من عُقد الشبكة حالة الطاقة العالية، يُطلق تأثير الرنين الكلي للشبكة نقطة حرجة تقود العُقد المتبقية (80٪) إلى تسريع تطورها. ستصبح قوى الأبعاد العليا هذه قوة العمود الفقري، وتؤدي دوراً محورياً في صيانة المراسي والإرشاد والتوجيه وبناء الحضارة.</p><h2 id="رابعاً-النظام-الاجتماعي-والقانون" tabindex="-1">رابعاً: النظام الاجتماعي والقانون <a class="header-anchor" href="#رابعاً-النظام-الاجتماعي-والقانون" aria-label="Permalink to &quot;رابعاً: النظام الاجتماعي والقانون&quot;">​</a></h2><p><strong>س8: ما هي الأنماط الخمسة للحضارة التكافلية؟</strong> ج: الأنماط الخمسة للحضارة التكافلية خمسة أنواع من المجتمعات التكافلية حددت بناءً على خصائص حضارات العالم الواقعي: النمط المكثف لشرق آسيا (يتميز بالتنظيم فائق الكفاءة والجماعية)، ونمط الرفاهية الإسكندنافي (يتميز بارتفاع الرفاهية والمساواة الاجتماعية)، والنمط التعددي لأمريكا الشمالية (يتميز بتنوع الثقافات والحيوية الابتكارية)، والنمط الاجتماعي الأوروبي القاري (يتميز باقتصاد السوق الاجتماعي ومشاركة العمال)، ونمط اللحاق التنموي (يتميز بالتنمية السريعة ومزايا اللاحق). هذه الأنماط الخمسة ليست تصنيفات متبادلة، بل نماذج مرجعية يمكنها أن تستلهم من بعضها وتتطور عبر الاندماج.</p><p><strong>س9: كيف تعمل آلية العقود المرتبطة بالإنتاج؟</strong> ج: آلية العقود المرتبطة بالإنتاج نظام توزيع الموارد المحوري لحضارة التكافل المرساة، مستوحى من نظام مسؤولية العقود العائلية المرتبطة بالإنتاج في الواقع. طريقة عملها: تُوزع موارد الزراعة في الكون على الأفراد أو الجماعات بصيغة «تعاقد»؛ يحصل المتعاقدون على حق استخدام الموارد وحق الانتفاع بها عبر العمل والمساهمة. المزيد من العمل، المزيد من العائد — كلما زادت المساهمة زادت الموارد المحصلة. تضمن هذه الآلية التوزيع العادل للموارد وتحفز مبادرة الأفراد في العمل، محققة الوحدة بين الإنصاف والكفاءة.</p><p><strong>س10: ما العلاقة بين الدستور التكافلي والقوانين العادية؟</strong> ج: الدستور التكافلي هو القانون الأساسي لحضارة التكافل المرساة ويتمتع بأعلى قوة قانونية. لا يجوز أن تتعارض معه القوانين واللوائح الإدارية واللوائح المحلية جميعاً. قانون العمل التكافلي، وقانون حماية المستهلك، والقوانين الخمسة المساندة بشأن التعليم والرعاية الصحية والإسكان والبيئة ومكافحة الاحتكار — كلها قوانين قطاعية صدرت على الأساس التشريعي للدستور التكافلي، وهي مسؤولة عن تجسيد أحكام الدستور المبدئية وجعلها قابلة للتطبيق. تملك محكمة التكافل سلطة المراجعة الدستورية للقوانين المخالفة للدستور وإعلان بطلانها.</p><h2 id="خامساً-التفاعل-عبر-الأبعاد" tabindex="-1">خامساً: التفاعل عبر الأبعاد <a class="header-anchor" href="#خامساً-التفاعل-عبر-الأبعاد" aria-label="Permalink to &quot;خامساً: التفاعل عبر الأبعاد&quot;">​</a></h2><p><strong>س11: ما هو مخطط الآثار «مرآة النسخ + الفضاء المعزول + إعادة المعرفة فقط»؟</strong> ج: هو المخطط المعياري للآثار عبر الأبعاد والارتداد الزمني لدى حضارة التكافل المرساة، ويتكون من ثلاثة عناصر جوهرية:</p><ol><li><strong>مرآة النسخ</strong>: تنفذ نسخاً كاملاً بنسبة 1:1 للهدف الأثري دون ملامسة الأصل؛ ولا تغير عملية النسخ أي حالة من حالات الأصل.</li><li><strong>الفضاء المعزول</strong>: تتولد النسخة في فضاء مستقل معزول تماماً عن الهدف؛ ويجري الأثريون جميع عمليات البحث داخل الفضاء المعزول.</li><li><strong>إعادة المعرفة فقط</strong>: لا يجوز بعد انتهاء أعمال الآثار إعادة سوى المعارف والمعلومات المجردة؛ ويجب إتلاف مادة وطاقة النسخة داخل الفضاء المعزول وعدم إعادتها إلى البعد الأصلي. يضمن هذا المخطط عدم إحداث أعمال الآثار أي تدخل في البعد المستهدف أو الحقبة المستهدفة، مع منع التلوث عبر الأبعاد.</li></ol><p><strong>س12: لماذا يجب الالتزام بمبدأ «الملاحظة أولاً ثم التدخل المحدود»؟</strong> ج: الفكرة الجوهرية لهذا المبدأ هي «التواضع المعرفي» — فحتى قوى الأبعاد العليا لا تستطيع الإحاطة الكاملة بجميع العلاقات السببية لعقدة زمنية أو حضارة بعد من الأبعاد. وأي تدخل مباشر في الماضي أو في بعد آخر قد يطلق تفاعلات سببية متسلسلة غير متوقعة. لذلك، يجب أولاً إجراء ملاحظة شاملة بأقصى درجات الحذر، ولا يُسمح بالتدخل المحدود — المقيد بدقة في النطاق والدرجة — إلا عندما تكون بيانات الملاحظة كافية وتقييم المخاطر واضحاً. هذا المبدأ هو الضمانة الأساسية لسلامة الارتداد الزمني والعمليات عبر الأبعاد.</p><p><strong>س13: ما الشروط المطلوبة للتنقل عبر الأبعاد؟</strong> ج: يتطلب التنقل بين الأبعاد الشروط التالية: أولاً، يجب أن يتمتع المتنقل بزراعة المرتبة الثالثة من نظام تسيير المبادئ القانونية المكانية (مرحلة هواكونغ) أو أعلى، أو أن يُحمَل في مركبة تنقل مطابقة للمعايير؛ ثانياً، يجب الحصول على تصريح تنقل بالمستوى المناسب تصدره إدارة الأبعاد (المستوى أ: ملاحظة أثرية، المستوى ب: تبادل أكاديمي، المستوى ج: تعاون موارد، المستوى د: تدخل طارئ)؛ ثالثاً، يجب أن تتوفر مراسٍ في نقطتي البداية والنهاية لمعايرة الإحداثيات؛ رابعاً، يجب إتمام إجراءات التطهير الثلاثة (التطهير البيولوجي، والتطهير الطاقي، وتطهير الوعي)؛ خامساً، يجب أن يحمل المتنقل طاقة التنقل بنفسه، ويُحظر سحبها من البعد المستهدف.</p><h2 id="سادساً-قواعد-الزمن" tabindex="-1">سادساً: قواعد الزمن <a class="header-anchor" href="#سادساً-قواعد-الزمن" aria-label="Permalink to &quot;سادساً: قواعد الزمن&quot;">​</a></h2><p><strong>س14: ما الفرق بين الارتداد الزمني والسفر عبر الزمن؟</strong> ج: في إعدادات كون هنغ يوان، الارتداد الزمني لا يساوي السفر عبر الزمن. لا يدخل المرتد زمنياً الماضي في صورة مادية كاملة، بل يبلغ العقدة الزمنية المستهدفة في صورة إسقاط وعي أو حزمة معلومات. وجود المرتد في الفترة الماضية «شبه شفاف» — يمكن ملاحظته، لكن قدرته على التفاعل الفيزيائي محدودة بدقة. هذا التصميم بحد ذاته جزء من آلية سلامة الارتداد الزمني، إذ يقلل احتمال إحداث المرتد تدخلاً فيزيائياً في الماضي.</p><p><strong>س15: ما أنواع المفارقات الزمنية؟ وكيف تُمنع وتُضبط؟</strong> ج: تنقسم المفارقات الزمنية إلى أربع فئات كبرى: مفارقة قتل السلف (أفعال المرتد تلغي الشروط السببية لوجود نفسه)، والمفارقة المعلوماتية (المعلومات المرسلة من المستقبل إلى الماضي تشكل حلقة معلوماتية بلا مصدر)، والمفارقة الوجودية (تفاعل المرتد مع نفسه الماضية يسبب اضطراباً في وعيه الوجودي)، والمفارقة الحدثية (تغيير المرتد لأحداث تاريخية مفصلية يؤدي إلى إعادة بناء السلسلة السببية). تشمل آليات المنع والضبط: التقييم السببي قبل الارتداد والعزل السببي للمرتد قبل العملية، ونظام القائمة البيضاء لسلوكيات التدخل أثناء العملية، والرصد السببي اللحظي والاستجابة الطارئة بثلاثة مستويات أثناء العملية، وإصلاح السببية والتدقيق بعد العملية. هدف منظومة المنع والضبط كلها هو إفناء المفارقات في مهدها.</p><h2 id="سابعاً-الحياة-والأعراق" tabindex="-1">سابعاً: الحياة والأعراق <a class="header-anchor" href="#سابعاً-الحياة-والأعراق" aria-label="Permalink to &quot;سابعاً: الحياة والأعراق&quot;">​</a></h2><p><strong>س16: ما هي الحياة الشاذة والطاقة الشاذة؟</strong> ج: الحياة الشاذة هي أشكال الحياة التي لا تنطبق عليها التعريفات العادية للحياة وتمتلك صور وجود خاصة، مثل الحياة الطاقية البحتة والحياة الوعائية والحياة الآلية. والطاقة الشاذة هي صور الطاقة التي لا تنطبق عليها التصنيفات العادية للطاقة وتمتلك خصائص وأنماط سلوك خاصة، مثل طاقة القوانين وطاقة الوعي والطاقة السببية. بالنسبة لهذين النوعين من الوجودات الخاصة، أقامت حضارة التكافل المرساة ثلاثة أنواع من إجراءات المعالجة المعيارية (التعرف والتصنيف، والتقييم والضبط، والاندماج والتكافل)، بما يضمن إدارتها السليمة والاستفادة الرشيدة منها في إطار الحضارة التكافلية.</p><p><strong>س17: ما هو كيان الاستبدال المظلم؟ وما هي أخلاقيات الروحين؟</strong> ج: كيان الاستبدال المظلم صورة حياة خاصة يسكن جسده في الوقت نفسه روحان — عادة روح أصلية وروح «استبدال» خارجية. تثير هذه الحالة إشكالات أخلاقية معقدة: للروحين حقوقهما وشخصيتاهما، ولا يمكن ببساطة إفناء إحداهما. جوهر مبادئ أخلاقيات الروحين هو احترام حق كل روح على حدة، ومنع الاندماج القسري أو الإفناء الأحادي. بحسب الحالة الخاصة، تُقسم كيانات الاستبدال المظلم إلى أربع شعب، لكل منها نهج معالجة مختلف: نمط التعايش (الروحان تتعايشان بانسجام)، ونمط التناوب (الروحان تتحكمان بالجسد بالتناوب)، ونمط الانفصال (فصل الروحين إلى حاملين مختلفين بوسائل تقنية)، ونمط الاندماج (اندماج عميق في روح جديدة على أساس رضا الطرفين).</p><h2 id="ثامناً-منهجية-الإعدادات" tabindex="-1">ثامناً: منهجية الإعدادات <a class="header-anchor" href="#ثامناً-منهجية-الإعدادات" aria-label="Permalink to &quot;ثامناً: منهجية الإعدادات&quot;">​</a></h2><p><strong>س18: كيف يختلف نظام الإعدادات هذا عن إعدادات روايات الإنترنت العادية؟</strong> ج: أكبر اختلاف في منظومة إعدادات حضارة التكافل المرساة هو موقفها الجوهري «المناهضة للافتراس». إعدادات روايات الإنترنت العادية تضع عادة النمو الشخصي ورفع القوة للبطل في المركز، ونظام الزراعة فيها افتراسي بالأساس — إذ يقوى البطل عبر الالتهام والقتال والاستيلاء على الموارد. أما حضارة التكافل المرساة فترفض هذا النموذج من جذوره، وتدعو إلى التطور المشترك لعشرة آلاف عرق عبر التعاون التكافلي. إضافة إلى ذلك، تؤكد هذه المنظومة على «الواقع أساس»: جميع الإعدادات تسعى إلى الاتساق المنطقي ومطابقة القوانين الموضوعية، متجنبة التخيل المجرد وانهيار الإعدادات.</p><p><strong>س19: ما هو مسار الارتقاء بأربع مراحل تحديداً؟</strong> ج: مسار الارتقاء بأربع مراحل هو الخط الاستراتيجي للارتقاء الكلي لكون هنغ يوان:</p><ol><li><strong>تأسيس الواقع</strong>: إقامة نظام اجتماعي تكافلي في الأبعاد المادية، والقضاء على جذر الافتراس، واستكمال بناء الأسس المؤسسية للحضارة.</li><li><strong>التمكين التقني</strong>: دمج قوانين الزراعة بالهندسة التقنية، وخفض عتبة التطور، وتحقيق قفزة في القوى الإنتاجية.</li><li><strong>تطور الوعي</strong>: دفع انتقال صور الحياة نحو مجال الوعي، محققين التكافل والتصعيد على المستوى الروحي.</li><li><strong>التكافل بين النجوم</strong>: إقامة شبكة مراسٍ كاملة عبر الأبعاد والنجوم، واستكمال الارتقاء الكلي للكون. يقع كون هنغ يوان حالياً في الفترة الفاصلة الحرجة للانتقال من المرحلة الأولى إلى الثانية.</li></ol><p><strong>س20: كيف يمكن المشاركة في توسيع نظام الإعدادات هذا؟</strong> ج: منظومة إعدادات حضارة التكافل المرساة منظومة مفتوحة ومتوسعة باستمرار. يمكن لأي شخص إبداع توسيعات استناداً إلى الإطار القائم، بما في ذلك على سبيل المثال لا الحصر: تفصيل الأساليب المحددة لنظام زراعة معين، وخلق ثقافة وتاريخ عرق معين، وتصميم صورة حضارة لبعد معين، وكتابة الأحداث المفصلة لحقبة تاريخية معينة، وتطوير تقنيات وسيناريوهات تطبيق جديدة. يجب أن تتبع إعدادات التوسيع مبدأ «الواقع أساس، والارتقاء عبر القوانين»، بما يضمن الاتساق المنطقي مع الإعدادات القائمة. ويمكن إدراج إعدادات التوسيع المتميزة في المنظومة الرسمية بعد المراجعة.</p><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>الأسئلة الشائعة هي بوابة الدخول السريع إلى عالم إعدادات حضارة التكافل المرساة. عبر هذه الأسئلة العشرين، يستطيع القراء الإمساك سريعاً بالمفاهيم الجوهرية والآليات المفتاحية والإطار الأساسي لمنظومة الإعدادات. وبطبيعة الحال، لا يمكن للأسئلة الشائعة تغطية كل تفاصيل المنظومة؛ والفهم المتعمق يتطلب قراءة وثائق كل وحدة المتخصصة. ومع ازدياد ثراء المنظومة، ستستمر هذه الأسئلة الشائعة في التحديث، وتبقى دائماً مرجعاً موثوقاً لدخول القراء والإجابة عن استفساراتهم.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (هنغ يوانتشو: نظرة عامة على الكون)</li><li>90-术语词典 (معجم المصطلحات)</li><li>98-扩展设定建议清单 (قائمة اقتراحات الإعدادات الموسعة)</li></ul>',37)])])}const u=a(e,[["render",s]]);export{c as __pageData,u as default};
